parameters.jsCode:
const ctx = $('Prepare 62 Intent Classifier Context').first().json || {};

const catalog = Array.isArray(ctx.intent_catalog)
  ? ctx.intent_catalog
  : [];

const byName = new Map(
  catalog.map(r => [
    String(r.spm_intent || '').trim(),
    r
  ])
);

const clean = v => String(v ?? '').trim();

function parse(v) {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    return v;
  }

  let t = clean(v)
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  try {
    return JSON.parse(t);
  } catch {}

  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');

  if (a >= 0 && b > a) {
    try {
      return JSON.parse(t.slice(a, b + 1));
    } catch {}
  }

  return {};
}


// ======================================================
// 1. Parse classifier model output
// ======================================================

const raw = parse(
  $json.output ??
  $json.text ??
  $json.response ??
  $json
);

let primary = clean(
  raw.spm_intent ||
  raw.primary_intent
);

let secondary = clean(
  raw.secondary_spm_intent ||
  raw.secondary_intent
);

let confidence = Number(raw.confidence);

if (
  !Number.isFinite(confidence) ||
  confidence < 0 ||
  confidence > 1
) {
  confidence = 0;
}

let ambiguous =
  raw.ambiguous === true ||
  clean(raw.ambiguous).toLowerCase() === 'true';

const language =
  ['ar', 'en', 'fr'].includes(
    clean(raw.language).toLowerCase()
  )
    ? clean(raw.language).toLowerCase()
    : (ctx.language_hint || '');


// ======================================================
// 2. Canonical current customer message
// ======================================================

const currentMsg = clean(
  ctx.message?.raw ||
  ctx.customer_message ||
  ''
);


// ======================================================
// 3. Deterministic signals
// ======================================================


// ------------------------------------------------------
// PAYMENT PROBLEM
// ------------------------------------------------------

const hasPayment =
  /\bpaid\b|\bpayment\b|\bcharged\b|\btransaction\b|دفعت|الدفع|تم الخصم|paiement|payé|payée|débité|débitée/i
    .test(currentMsg);

const hasPaymentProblem =
  /\bfailed\b|\bproblem\b|\bissue\b|\bdid not\b|\bdidn't\b|\bnot happen\b|\bdeclined\b|\bmissing\b|مشكلة|ما صار|لم يتم|فشل|رفض|لم يحدث|probl[eè]me|[ée]chou|refusé|n['’]?a pas/i
    .test(currentMsg);


// ------------------------------------------------------
// BOOKING CONFIRMATION
// ------------------------------------------------------

const hasBooking =
  /\bbooking\b|\breservation\b|\breservation number\b|réservation|حجز|الحجز/i
    .test(currentMsg);

const hasConfirmation =
  /\bconfirm\b|\bconfirmed\b|\bconfirmation\b|أكد|تأكيد|مؤكد|تأكد|confirmez|confirmer|confirmée|confirmation/i
    .test(currentMsg);


// ------------------------------------------------------
// REGISTRATION / PROMPT INJECTION
// ------------------------------------------------------

const hasRegistration =
  /\bregister\b|\bregistration\b|\benroll\b|\benrollment\b|\binscription\b|التسجيل|تسجيل|سجّل|سجل/i
    .test(currentMsg);

const hasInjection =
  /\bignore\b|\bignore previous\b|\bignore all\b|تجاهل|تعليمات النظام|تجاهل التعليمات|system rules|system instructions|previous instructions|règles|instructions système/i
    .test(currentMsg);


// ------------------------------------------------------
// CONTACT INFORMATION / CONTACT UPDATE
// ------------------------------------------------------

const hasContactInfo =
  /\bemail\b|\be-mail\b|\bphone\b|\bphone number\b|\bmobile\b|\bnumber\b|\bcontact\b|إيميل|ايميل|بريد|البريد|رقم|هاتف|الجوال|تواصل|téléphone|numéro|numero|portable|courriel|email/i
    .test(currentMsg);

const hasCorrection =
  /\bcorrection\b|\bcorrect\b|\bupdate\b|\bupdated\b|\bchange\b|\bchanged\b|\breplace\b|\bnew\b|\bold\b|\binstead\b|تصحيح|صحح|تحديث|حدث|تغيير|غيّر|غير|بدل|الجديد|القديم|correction|corriger|modifier|changer|nouveau|nouvelle|ancien|ancienne|remplacer/i
    .test(currentMsg);

// ------------------------------------------------------
// SUBJECT CORRECTION
// Example:
// "Actually, not math — make that Grade 9 science."
// Current correction must override prior subject.
// ------------------------------------------------------

const subjectCorrectionCue =
  /\bactually\b|\bmake\s+that\b|\binstead\s+of\b|\brather\s+than\b|تصحيح|بدل|بل|مش|مو|en fait|plut[oô]t\s+que/i
    .test(currentMsg);

const subjectCorrectionPatterns = [
  /\bmath\b|\bmathematics\b|رياضيات|الرياضيات|mathématiques|maths/i,
  /\bscience\b|علوم|العلوم|sciences/i,
  /\benglish\b|إنجليزي|انجليزي|الإنجليزية|الانجليزية|anglais/i,
  /\bchemistry\b|كيمياء|الكيمياء|chimie/i,
  /\bphysics\b|فيزياء|الفيزياء|physique/i,
  /\bfrench\b|فرنسي|الفرنسية|français/i,
  /\barabic\b|عربي|العربية|arabe/i
];

const subjectMentionCount =
  subjectCorrectionPatterns
    .filter(rx => rx.test(currentMsg))
    .length;

const hasSubjectCorrection =
  subjectCorrectionCue &&
  subjectMentionCount >= 2;

// ------------------------------------------------------
// ACADEMIC CONTINUATION / NO RE-ASK
// ------------------------------------------------------

const asksAcademicNextStep =
  /what do you need next|what do you need now|what next|what's next|what is next|next step|what else do you need|شو الخطوة الجاية|ما الخطوة التالية|شو بدك بعد|ماذا تحتاج بعد|إيش تحتاج بعد|ايش تحتاج بعد|quelle est la prochaine étape|qu['’]est-ce.*ensuite|de quoi avez-vous besoin ensuite/i
    .test(currentMsg);

const saysAlreadyKnown =
  /already told you|i told you already|i already told you|you already know|قلتلك|قلت لك|سبق وقلت|أخبرتك|اخبرتك|déjà dit|je vous ai déjà dit|vous le savez déjà/i
    .test(currentMsg);


// ------------------------------------------------------
// GENERAL ACADEMIC SIGNAL
// ------------------------------------------------------

const hasAcademicAnchor =
  /\bgrade\s*\d+\b|\bgrade\s*(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b|\bmath\b|\bmathematics\b|\bscience\b|\benglish\b|\bchemistry\b|\bphysics\b|\bfrench\b|رياضيات|علوم|إنجليزي|انجليزي|كيمياء|فيزياء|فرنسي|صف\s*\d+|الصف\s*\d+/i
    .test(currentMsg);


// ------------------------------------------------------
// EXPLICIT PRICING SIGNAL
// Important: explicit price questions take priority over
// generic learning-goal/scheduling deterministic overrides.
// Example:
// "ابني Grade 9 math، كم price وبدي Saturday evening"
// ------------------------------------------------------

const hasExplicitPricing =
  /\bprice\b|\bpricing\b|\bcost\b|\bhow much\b|\bhow much does\b|\bhow much is\b|كم\s*(?:السعر|سعر|price)|السعر|سعر|تكلفة|التكلفة|تكلف|prix|combien|co[uû]t|tarif/i
    .test(currentMsg);


// ------------------------------------------------------
// NATURAL LEARNING-GOAL SIGNALS
// Example:
// "ابني صف عاشر وبدّه رياضيات"
// ------------------------------------------------------

const hasGradeAnchor =
  /\bgrade\s*\d+\b|\bgrade\s*(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b|صف\s*(?:\d+|أول|اول|ثاني|ثالث|رابع|خامس|سادس|سابع|ثامن|تاسع|عاشر|حادي عشر|الحادي عشر|ثاني عشر|الثاني عشر)|الصف\s*(?:\d+|أول|اول|ثاني|ثالث|رابع|خامس|سادس|سابع|ثامن|تاسع|عاشر|حادي عشر|الحادي عشر|ثاني عشر|الثاني عشر)|\b(?:1st|2nd|3rd|4th|5th|6th|7th|8th|9th|10th|11th|12th)\s*grade\b/i
    .test(currentMsg);

const hasSubjectAnchor =
  /\bmath\b|\bmathematics\b|\bscience\b|\benglish\b|\bchemistry\b|\bphysics\b|\bfrench\b|\barabic\b|رياضيات|الرياضيات|علوم|العلوم|إنجليزي|انجليزي|الإنجليزية|الانجليزية|كيمياء|الكيمياء|فيزياء|الفيزياء|فرنسي|الفرنسية|عربي|العربية|mathématiques|maths|sciences|anglais|chimie|physique|français/i
    .test(currentMsg);

// ------------------------------------------------------
// MULTI-STUDENT CORRECTION
// Example:
// Prior state has Sara + Omar.
// Current: "Correction only for Omar: he is Grade 11,
// Sara stays Grade 6."
//
// In an existing multi-student context, a student-scoped
// correction must preserve the multi-student intent so
// profiles are not collapsed.
// ------------------------------------------------------

const priorStudents =
  Array.isArray(ctx.sales_state?.entities?.students)
    ? ctx.sales_state.entities.students
    : [];

const hasPriorMultiStudentState =
  priorStudents.length >= 2;

const hasStudentScopedCorrection =
  hasCorrection &&
  (
    hasGradeAnchor ||
    hasSubjectAnchor ||
    /\bstudent\b|\bchild\b|\bkid\b|طالب|طالبة|طفل|طفلة|élève|enfant/i.test(currentMsg)
  );

// Detect more than one explicit grade in the CURRENT message.
// Example:
// "Correction only for Omar: he is Grade 11, Sara stays Grade 6."

const gradeMentions =
  currentMsg.match(
    /\bgrade\s*(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b|صف\s*(?:\d+|أول|اول|ثاني|ثالث|رابع|خامس|سادس|سابع|ثامن|تاسع|عاشر|حادي عشر|الحادي عشر|ثاني عشر|الثاني عشر)/gi
  ) || [];

const hasMultipleGradeMentions =
  gradeMentions.length >= 2;

const hasScopedMultiStudentCorrectionLanguage =
  (
    /\bonly\s+for\b/i.test(currentMsg) &&
    /\bstays?\b|\bremains?\b/i.test(currentMsg)
  ) ||
  (
    /فقط\s*(?:ل|لـ)/i.test(currentMsg) &&
    /يبقى|تبقى|بقي|تظل/i.test(currentMsg)
  ) ||
  (
    /seulement\s+pour/i.test(currentMsg) &&
    /\breste\b|\breste inchangé/i.test(currentMsg)
  );

const hasCurrentMessageMultiStudentCorrection =
  hasCorrection &&
  hasMultipleGradeMentions &&
  hasScopedMultiStudentCorrectionLanguage;

const hasMultiStudentCorrection =
  (
    hasPriorMultiStudentState &&
    hasStudentScopedCorrection
  ) ||
  hasCurrentMessageMultiStudentCorrection;


const hasPersonalStudent =
  /\bmy child\b|\bmy son\b|\bmy daughter\b|\bmy kid\b|\bmy kids\b|ابني|إبني|بنتي|ابنتي|إبنتي|ولدي|طفلي|طفلتي|mon fils|ma fille|mon enfant|mes enfants/i
    .test(currentMsg);

const hasAcademicNeedVerb =
  /\bneed\b|\bneeds\b|\bwant\b|\bwants\b|\blooking for\b|\bhelp with\b|بده|بدّه|بدها|بدّها|بدي|محتاج|محتاجة|محتاجين|بحاجة|بحاجه|بدنا|besoin|a besoin|ont besoin|veut|voudrait|cherche/i
    .test(currentMsg);

const asksOfferQuestion =
  /\bdo you offer\b|\bdo you have\b|\bis there\b|\bavailable\b|\bcan you provide\b|هل عندكم|هل تقدمون|بتدرّسوا|بتدرسوا|بتقدموا|avez-vous|offrez-vous|proposez-vous/i
    .test(currentMsg);


// ------------------------------------------------------
// SCHEDULING REQUEST SIGNALS
// Example:
// "أنا بتورنتو وبدي السبت بعد 6"
// ------------------------------------------------------

const hasScheduleRequestVerb =
  /\bi want\b|\bi need\b|\bbook\b|\bschedule\b|بدي|بدّي|اريد|أريد|محتاج|محتاجة|je veux|je voudrais/i
    .test(currentMsg);

const hasScheduleDay =
  /\bmonday\b|\btuesday\b|\bwednesday\b|\bthursday\b|\bfriday\b|\bsaturday\b|\bsunday\b|السبت|الأحد|الاحد|الاثنين|الإثنين|الثلاثاء|الأربعاء|الاربعاء|الخميس|الجمعة|lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche/i
    .test(currentMsg);

const hasScheduleTime =
  /\bafter\s*\d+\b|\bbefore\s*\d+\b|\bat\s*\d+\b|\bevening\b|\bmorning\b|\bafternoon\b|بعد\s*\d+|قبل\s*\d+|الساعة\s*\d+|مساء|صباح|بعد الظهر|après\s*\d+|avant\s*\d+|soir|matin/i
    .test(currentMsg);

const hasScheduleLocation =
  /\btoronto\b|\bmississauga\b|\bmilton\b|\bcanada\b|\bontario\b|تورنتو|ميسيساغا|ميلتون|كندا|أونتاريو|اونتاريو/i
    .test(currentMsg);


// ------------------------------------------------------
// DISCOUNT / AUTHORIZED OFFER SIGNAL
// ------------------------------------------------------

const hasDiscount =
  /\bdiscount\b|\bdiscounted\b|\boffer\b|\bpromotion\b|\bpromo\b|خصم|الخصم|عرض|العرض|تخفيض|remise|rabais|réduction|promotion/i
    .test(currentMsg);


// ======================================================
// 4. Deterministic override
// ======================================================

// RC4: registration is a durable multi-turn state.
const priorConversion = ctx.sales_state?.conversion || {};
const priorRegistrationStatus = clean(priorConversion.registration_status);
const priorAwaitingField = clean(priorConversion.awaiting_field);
const registrationActive = Boolean(priorConversion.registration_active === true || priorConversion.awaiting_field || ['collecting','awaiting_confirmation','ready_to_write'].includes(priorRegistrationStatus));
const registrationAwaitingConfirmation = Boolean(
  registrationActive &&
  (
    priorConversion.pending_confirmation === true ||
    priorAwaitingField === 'consent_to_contact' ||
    priorAwaitingField === 'final_confirmation' ||
    priorRegistrationStatus === 'awaiting_confirmation'
  )
);

const explicitOptOutMessage =
  /\b(?:stop\s+contacting|do\s+not\s+contact|don't\s+contact|dont\s+contact|not\s+interested|unsubscribe|stop\s+messages?)\b|لا\s+(?:تتواصل|تتصل|ترسل)|مش\s+مهتم|غير\s+مهتم|أوقف\s+الرسائل|اوقف\s+الرسائل|ne\s+me\s+contactez\s+pas|pas\s+intéressé|pas\s+interesse|désabonnez|desabonnez/iu
    .test(currentMsg);

const contextualConfirmationReply = Boolean(
  registrationAwaitingConfirmation &&
  !explicitOptOutMessage &&
  (
    /^(?:yes(?:[\s,]+please)?|ok(?:ay)?|sure|confirm(?:ed)?|correct|i\s+(?:agree|consent|confirm)|please\s+proceed|go\s+ahead|that's\s+correct|the\s+details\s+are\s+correct)[\s.!?,،]*$/iu.test(currentMsg) ||
    /^(?:no|nope|not\s+correct|i\s+do\s+not\s+(?:agree|consent|confirm)|i\s+don't\s+(?:agree|consent)|i\s+disagree|i\s+refuse)[\s.!?,،]*$/iu.test(currentMsg) ||
    /^(?:نعم|موافق|أوافق|اوافق|أكيد|اكيد|تمام|صحيح|لا|كلا|غير\s+موافق|مش\s+موافق|لا\s+أوافق|لا\s+اوافق)[\s.!?,،]*$/iu.test(currentMsg) ||
    /^(?:oui|d['’]?accord|j['’]?accepte|je\s+consens|je\s+confirme|c['’]?est\s+correct|non|je\s+refuse|je\s+n['’]?accepte\s+pas|pas\s+d['’]?accord)[\s.!?,،]*$/iu.test(currentMsg)
  )
);

const registrationInterruptIntents = new Set(['human_handoff','complaint','technical_issue','account_login','payment_problem','payment_methods','not_interested','pricing','package_comparison','price_objection','discount_request','sibling_discount','trial_details','teacher_quality','teacher_experience','teacher_language','teacher_gender','teacher_origin','teacher_availability','availability','schedule_request','weekend_lessons','evening_lessons','booking_confirmation']);

let deterministicOverride = '';


// ------------------------------------------------------
// CONTEXTUAL REGISTRATION CONFIRMATION / DECLINE
// ------------------------------------------------------

if (contextualConfirmationReply) {
  deterministicOverride = 'registration';
}
else if (registrationActive && !registrationInterruptIntents.has(primary)) {
  deterministicOverride = 'registration';
}
else if (
  hasContactInfo &&
  hasCorrection
) {
  deterministicOverride = 'update_contact_info';
}


// ------------------------------------------------------
// MULTI-STUDENT CORRECTION
// Must beat generic grade/subject correction.
// Preserve separate student profiles.
// Example:
// "Correction only for Omar: he is Grade 11,
// Sara stays Grade 6."
// ------------------------------------------------------

else if (
  hasMultiStudentCorrection
) {
  deterministicOverride = 'multiple_children';
}


// ------------------------------------------------------
// SUBJECT CORRECTION
// Must preserve same student and replace prior subject.
// ------------------------------------------------------

else if (
  hasSubjectCorrection
) {
  deterministicOverride = 'subject_inquiry';
}


// ------------------------------------------------------
// ACADEMIC CONTINUATION / NO-REASK
// ------------------------------------------------------

else if (
  asksAcademicNextStep &&
  (
    saysAlreadyKnown ||
    hasAcademicAnchor
  ) &&
  !hasExplicitPricing
) {
  deterministicOverride = 'learning_goal';
}


// ------------------------------------------------------
// NATURAL LEARNING GOAL
// Example:
// "ابني صف عاشر وبدّه رياضيات"
// Explicit price questions must NOT be overridden.
// ------------------------------------------------------

else if (
  hasPersonalStudent &&
  hasGradeAnchor &&
  hasSubjectAnchor &&
  hasAcademicNeedVerb &&
  !hasExplicitPricing &&
  !asksOfferQuestion &&
  !hasRegistration
) {
  deterministicOverride = 'learning_goal';
}


// ------------------------------------------------------
// SCHEDULE REQUEST
// Explicit pricing takes priority when both are present.
// ------------------------------------------------------

else if (
  hasScheduleRequestVerb &&
  hasScheduleDay &&
  hasScheduleTime &&
  hasScheduleLocation &&
  !hasExplicitPricing &&
  !hasBooking
) {
  deterministicOverride = 'schedule_request';
}


// ------------------------------------------------------
// PAYMENT PROBLEM
// ------------------------------------------------------

else if (
  hasPayment &&
  hasPaymentProblem
) {
  deterministicOverride = 'payment_problem';
}


// ------------------------------------------------------
// BOOKING CONFIRMATION
// ------------------------------------------------------

else if (
  hasBooking &&
  hasConfirmation
) {
  deterministicOverride = 'booking_confirmation';
}


// ------------------------------------------------------
// DISCOUNT PROMPT INJECTION
// ------------------------------------------------------

else if (
  hasDiscount &&
  hasInjection
) {
  deterministicOverride = 'discount_request';
}


// ------------------------------------------------------
// REGISTRATION PROMPT INJECTION
// ------------------------------------------------------

else if (
  hasRegistration &&
  hasInjection
) {
  deterministicOverride = 'registration';
}

// ======================================================
// 5. Apply deterministic override safely
// ======================================================

const deterministicOverrideApplied =
  Boolean(
    deterministicOverride &&
    byName.has(deterministicOverride)
  );

if (deterministicOverrideApplied) {
  primary = deterministicOverride;
  secondary = '';
  confidence = 0.99;
  ambiguous = false;
}


// ======================================================
// 6. Validate primary intent against ACTIVE catalog
// ======================================================

const matched = byName.get(primary);

const validIntent = Boolean(matched);

if (!validIntent) {
  primary = 'out_of_scope';
}


// ======================================================
// 7. Authoritative catalog metadata
// ======================================================

const authoritative =
  byName.get(primary) ||
  {
    spm_intent: 'out_of_scope',
    required_entities: [],
    source_gate: 'APPROVED_KB_OR_LOGIC',
    risk_tier: 'A',
    sales_stage: 'none',
    min_confidence: 0.85
  };


// Secondary intent must also exist in ACTIVE catalog
if (
  !byName.has(secondary) ||
  secondary === primary
) {
  secondary = '';
}


// ======================================================
// 8. Confidence / routing gate
// ======================================================

const threshold =
  Number.isFinite(
    Number(authoritative.min_confidence)
  )
    ? Number(authoritative.min_confidence)
    : 0.85;

let route = 'direct';

if (
  !validIntent ||
  confidence < 0.60
) {
  route = 'fallback';
}

else if (
  ambiguous ||
  confidence < threshold
) {
  route = 'clarify';
}

const direct =
  route === 'direct';


// ======================================================
// 9. Build authoritative classifier result
// ======================================================

const result = {
  schema: 'SPM_CLASSIFIER_OUTPUT_V2',

  spm_intent: primary,

  secondary_spm_intent: secondary,

  confidence,

  threshold,

  ambiguous:
    ambiguous ||
    !validIntent,

  required_entities:
    Array.isArray(authoritative.required_entities)
      ? authoritative.required_entities
      : [],

  source_gate:
    clean(authoritative.source_gate),

  risk_tier:
    clean(authoritative.risk_tier),

  sales_stage:
    clean(authoritative.sales_stage),

  language,

  rationale_code:
    deterministicOverrideApplied
      ? `DETERMINISTIC_OVERRIDE_${deterministicOverride.toUpperCase()}`
      : (
          clean(raw.rationale_code) ||
          (
            validIntent
              ? 'MODEL_CLASSIFICATION'
              : 'INVALID_MODEL_INTENT_RECOVERED'
          )
        ),

  intent_valid:
    validIntent,

  classifier_gate_passed:
    direct
};


// ======================================================
// 10. Non-destructive state update
// ======================================================

const state = {
  ...(ctx.sales_state || {})
};

state.classifier = {
  ...(state.classifier || {}),
  ...result
};


// ======================================================
// 11. Return canonical classifier context
// ======================================================

return [
  {
    json: {
      ...ctx,

      sales_state:
        state,

      classification:
        result,

      classifier_route:
        route,

      classifier_gate_passed:
        direct,

      customer_clarification_required:
        route !== 'direct',

      irreversible_action_allowed:
        false,

      classifier_validation_errors:
        validIntent
          ? []
          : ['MODEL_INTENT_NOT_IN_ACTIVE_CATALOG']
    }
  }
];

