const context=$('Build WU89 Extraction Context').first().json || {};
const schemaRows=Array.isArray(context.entity_schema)?context.entity_schema:[];
const schema=new Map(schemaRows.map(r=>[String(r.entity_name||'').trim(),r]));
const msg=String(context?.message?.raw??'').trim();

function clean(v){return String(v??'').trim();}

function stripBoundaryPunctuation(v){
 const s=clean(v);
 return s
   .replace(/^[\s<([{'"“‘«]+/u,'')
   .replace(/[\s>\])}'"”’».,;:!?،؛؟]+$/u,'')
   .trim();
}

function parseObj(v){
 if(v&&typeof v==='object'&&!Array.isArray(v)) return v;
 let s=clean(v).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim();
 if(!s)return {};
 try{return JSON.parse(s)}catch{}
 const a=s.indexOf('{'),b=s.lastIndexOf('}');
 if(a>=0&&b>a){try{return JSON.parse(s.slice(a,b+1))}catch{}}
 return {};
}

function arabicDigits(s){
 return String(s??'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));
}

function searchNorm(s){
 return arabicDigits(stripBoundaryPunctuation(s))
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g,'')
   .replace(/[\u064B-\u065F\u0670\u0640]/g,'')
   .replace(/[إأآٱ]/g,'ا')
   .replace(/ى/g,'ي')
   .replace(/\s+/g,' ')
   .trim();
}

function normSubject(v){
 const s=searchNorm(v);

 if(/^(math|maths|mathematics|mathematiques|رياضيات|ماث)$/.test(s)) return 'Math';

 if(/^(english|anglais|انجليزي|الانجليزيه|الانجليزية|اللغه الانجليزيه|اللغة الانجليزية)$/.test(s))
   return 'English';

 if(/^(french|francais|فرنسي|الفرنسيه|الفرنسية|اللغه الفرنسيه|اللغة الفرنسية)$/.test(s))
   return 'French';

 if(/^(science|sciences|علوم|العلوم)$/.test(s))
   return 'Science';

 if(/^(physics|physique|فيزياء|الفيزياء)$/.test(s))
   return 'Physics';

 if(/^(chemistry|chimie|كيمياء|الكيمياء)$/.test(s))
   return 'Chemistry';

 if(/^(arabic|arabe|عربي|العربيه|العربية|اللغه العربيه|اللغة العربية)$/.test(s))
   return 'Arabic';

 return stripBoundaryPunctuation(v);
}

function normGrade(v){
 let s=searchNorm(v)
   .replace(/\b(?:grade|gr|g|class|niveau)\s*/g,'')
   .replace(/الصف\s*/g,'')
   .trim();

 const words={
   'اول':'1',
   'الأول':'1',
   'الاول':'1',
   'ثاني':'2',
   'الثاني':'2',
   'ثالث':'3',
   'الثالث':'3',
   'رابع':'4',
   'الرابع':'4',
   'خامس':'5',
   'الخامس':'5',
   'سادس':'6',
   'السادس':'6',
   'سابع':'7',
   'السابع':'7',
   'ثامن':'8',
   'الثامن':'8',
   'تاسع':'9',
   'التاسع':'9',
   'عاشر':'10',
   'العاشر':'10',
   'حادي عشر':'11',
   'الحادي عشر':'11',
   'ثاني عشر':'12',
   'الثاني عشر':'12'
 };

 if(words[s])s=words[s];

 const m=s.match(
   /(?:^|\b)(1[0-2]|[1-9])(?:e|er|eme|ème|th|st|nd|rd)?(?:\b|$)/i
 );

 return m
   ? `Grade ${m[1]}`
   : stripBoundaryPunctuation(v);
}

function normCountry(v){
 const s=searchNorm(v);

 if(['canada','كندا'].includes(s))
   return 'Canada';

 if([
   'usa',
   'us',
   'u.s.',
   'united states',
   'united states of america',
   'america',
   'etats-unis',
   'etats unis',
   'امريكا',
   'الولايات المتحده',
   'الولايات المتحدة'
 ].includes(s))
   return 'United States';

 return stripBoundaryPunctuation(v);
}

function normLang(v){
 const s=searchNorm(v);

 if(/^(arabic|arabe|عربي|العربيه|العربية)(?:\b|\s|$)/.test(s))
   return 'Arabic';

 if(/^(english|anglais|انجليزي|الانجليزيه|الانجليزية)(?:\b|\s|$)/.test(s))
   return 'English';

 if(/^(french|francais|فرنسي|الفرنسيه|الفرنسية)(?:\b|\s|$)/.test(s))
   return 'French';

 return stripBoundaryPunctuation(v);
}

function normalizePhone(raw){
 const s=stripBoundaryPunctuation(raw);
 const hasLeadingPlus=s.startsWith('+');
 const digits=s.replace(/\D/g,'');

 return (hasLeadingPlus?'+':'')+digits;
}

function isValidIanaTimezone(v){
 const s=stripBoundaryPunctuation(v);

 if(
   !s ||
   !/^[A-Za-z0-9._+\-]+(?:\/[A-Za-z0-9._+\-]+)+$/.test(s)
 ){
   return false;
 }

 try{
   new Intl.DateTimeFormat(
     'en-US',
     {timeZone:s}
   ).format(new Date(0));

   return true;
 }catch{
   return false;
 }
}

function normalize(name,raw){

 if([
   'parent_name',
   'student_name',
   'transaction_reference',
   'lesson_id',
   'booking_id',
   'lead_id',
   'student_id',
   'teacher_id',
   'city'
 ].includes(name)){
   return stripBoundaryPunctuation(raw);
 }

 if(name==='email'){
   return stripBoundaryPunctuation(raw)
     .toLowerCase();
 }

 if(name==='phone'){
   return normalizePhone(raw);
 }

 if(name==='subject'){
   return normSubject(raw);
 }

 if(name==='subjects'){
   return Array.isArray(raw)
     ? raw.map(normSubject).filter(Boolean)
     : [normSubject(raw)].filter(Boolean);
 }

 if(name==='grade'){
   return normGrade(raw);
 }

 if(name==='grades'){
   return Array.isArray(raw)
     ? raw.map(normGrade).filter(Boolean)
     : [normGrade(raw)].filter(Boolean);
 }

 if(name==='country'){
   return normCountry(raw);
 }

 if([
   'preferred_language',
   'teaching_language'
 ].includes(name)){
   return normLang(raw);
 }

 if(name==='number_of_students'){
   const m=arabicDigits(
     stripBoundaryPunctuation(raw)
   ).match(/\d+/);

   const n=m
     ? Number(m[0])
     : NaN;

   return Number.isInteger(n) && n>0
     ? n
     : stripBoundaryPunctuation(raw);
 }

 if(name==='timezone'){
   return stripBoundaryPunctuation(raw);
 }

 return stripBoundaryPunctuation(raw);
}

function validStatus(name,canonical,row){

 if(
   canonical===undefined ||
   canonical===null ||
   canonical===''
 ){
   return 'rejected';
 }

 const s=String(canonical);

 if(name==='email'){
   return /^[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$/i.test(s)
     ? 'valid'
     : 'needs_validation';
 }

 if(name==='phone'){
   return /^\+?\d{7,15}$/.test(s)
     ? 'valid'
     : 'needs_validation';
 }

 if(name==='timezone'){
   return isValidIanaTimezone(s)
     ? 'valid'
     : 'needs_validation';
 }

 if(name==='grade'){
   return /^Grade\s+(?:[1-9]|1[0-2])$/i.test(s)
     ? 'valid'
     : 'needs_validation';
 }

 if(name==='grades'){
   const vals=Array.isArray(canonical)
     ? canonical
     : [canonical];

   return (
     vals.length>0 &&
     vals.every(
       v=>/^Grade\s+(?:[1-9]|1[0-2])$/i.test(String(v))
     )
   )
     ? 'valid'
     : 'needs_validation';
 }

 if([
   'preferred_language',
   'teaching_language'
 ].includes(name)){
   return [
     'English',
     'Arabic',
     'French'
   ].includes(s)
     ? 'valid'
     : 'needs_validation';
 }

 if(name==='number_of_students'){
   return (
     Number.isInteger(canonical) &&
     canonical>0 &&
     canonical<=20
   )
     ? 'valid'
     : 'needs_validation';
 }

 if(name==='subject'){
   return [
     'Math',
     'English',
     'French',
     'Science',
     'Physics',
     'Chemistry',
     'Arabic'
   ].includes(s)
     ? 'valid'
     : 'needs_validation';
 }

 if(name==='subjects'){
   const vals=Array.isArray(canonical)
     ? canonical
     : [canonical];

   return (
     vals.length>0 &&
     vals.every(
       v=>[
         'Math',
         'English',
         'French',
         'Science',
         'Physics',
         'Chemistry',
         'Arabic'
       ].includes(String(v))
     )
   )
     ? 'valid'
     : 'needs_validation';
 }

 if([
   'booking_id',
   'lesson_id',
   'transaction_reference',
   'payment_status',
   'lesson_status',
   'lead_id',
   'student_id',
   'teacher_id'
 ].includes(name)){
   return 'needs_validation';
 }

 return 'valid';
}

const raw=parseObj(
 $json.output ??
 $json.text ??
 $json.response ??
 $json
);

const correctionSignal=
 /\b(?:actually|correction|correct|change|update|instead)\b|(?:تصحيح|تعديل|غير|غيّر|لا قصدي|قصدي)/i
 .test(msg);

const records=[];
const seen=new Set();
const singleValueIndex=new Map();

const multiValueEntities=new Set([
 'subjects',
 'grades'
]);

function add(
 name,
 rawValue,
 confidence=0.8,
 source='customer'
){
 if(
   !schema.has(name) ||
   rawValue===undefined ||
   rawValue===null ||
   rawValue===''
 ){
   return;
 }

 const key=
   name+'|'+JSON.stringify(rawValue);

 if(seen.has(key))
   return;

 seen.add(key);

 const row=schema.get(name);
 const canonical=normalize(name,rawValue);

 const rec={
   entity:name,
   raw:rawValue,
   canonical,
   confidence:
     Math.max(
       0,
       Math.min(
         1,
         Number(confidence)||0.8
       )
     ),
   source,
   status:validStatus(
     name,
     canonical,
     row
   ),
   sensitivity:
     row.sensitivity||null,
   is_correction:Boolean(
     raw.correction_detected ||
     correctionSignal
   )
 };

 if(
   !multiValueEntities.has(name) &&
   singleValueIndex.has(name)
 ){
   const idx=
     singleValueIndex.get(name);

   if(
     rec.confidence >
     Number(
       records[idx]?.confidence||0
     )
   ){
     records[idx]=rec;
   }

   return;
 }

 records.push(rec);

 if(!multiValueEntities.has(name)){
   singleValueIndex.set(
     name,
     records.length-1
   );
 }
}

// Explicit labeled values from the CURRENT
// customer message are authoritative.
function setAuthoritative(
 name,
 rawValue,
 source='customer_deterministic_labeled_authoritative'
){
 if(
   !schema.has(name) ||
   rawValue===undefined ||
   rawValue===null ||
   rawValue===''
 ){
   return;
 }

 const row=schema.get(name);
 const canonical=normalize(
   name,
   rawValue
 );

 const rec={
   entity:name,
   raw:rawValue,
   canonical,
   confidence:1,
   source,
   status:validStatus(
     name,
     canonical,
     row
