   '(?:^|[\\n\\r;,،؛]|\\s)'+
   labelPattern+
   '\\s*:\\s*'+
   '(.+?)'+
   '(?='+
     '(?:\\s*[.!?؟]\\s*)?'+
     '(?:'+nextLabels+')'+
     '\\s*:'+
     '|(?:\\s*[.!?؟]\\s*)?'+
     '(?:grade|gr|g)'+
     '\\s*(?:1[0-2]|[1-9])\\b'+
     '|[\\n\\r;,،؛]'+
     '|$'+
   ')',
   'iu'
 );

 const m=msg.match(rx);

 return m
   ? stripBoundaryPunctuation(m[1])
   : '';
}

