function compactReply(s){
 return clean(s)
   .replace(
     /^[\s"'“”‘’]+|[\s"'“”‘’.,!?]+$/g,
     ''
   )
   .trim();
}

function plausibleName(s){
 const t=compactReply(s);

 return (
   t.length>=2 &&
   t.length<=100 &&
   /^[\p{L}\p{M}][\p{L}\p{M}'’ .-]*$/u.test(t) &&
   !/\b(?:phone|email|grade|subject|country|city|timezone|register|price|math|science)\b/i.test(t)
 );
}

function awaitedValue(field,s){

 const t=compactReply(s);

 if(!t)
   return '';

 if(
   field==='parent_name' ||
   field==='student_name'
 ){
   let v=t
     .replace(
       /^(?:my\s+name\s+is|i\s+am|parent(?:'s)?\s+name\s+is|guardian(?:'s)?\s+name\s+is)\s+/i,
       ''
     )
     .replace(
       /^(?:my\s+(?:son|daughter|child)(?:'s)?\s+name\s+is|student(?:'s)?\s+name\s+is|his\s+name\s+is|her\s+name\s+is)\s+/i,
       ''
     );

   return plausibleName(v)
     ? v
     : '';
 }

 if(field==='phone'){
   const m=
     t.match(
       /\+?\d[\d\s().-]{6,}\d/
     );

   if(!m)
     return '';

   const digs=
     m[0].replace(/\D/g,'');

   return (
     digs.length>=8 &&
     digs.length<=15
   )
     ? m[0]
     : '';
 }

 if(field==='email'){
   const m=
     t.match(
       /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/
     );

   return m
     ? m[0]
     : '';
 }

 if(field==='country'){
   const v=normCountry(t);

   return (
     v &&
     v.length<=80
   )
     ? v
     : '';
 }

 if(field==='city'){
   return (
     t.length>=2 &&
     t.length<=100 &&
     /[\p{L}]/u.test(t)
   )
     ? t
     : '';
 }

 if(field==='timezone'){
   const m=
     t.match(
       /\b[A-Za-z0-9._+\-]+(?:\/[A-Za-z0-9._+\-]+)+\b/
     );

   return (
     m &&
     isValidIanaTimezone(m[0])
   )
     ? m[0]
     : '';
 }

 if(field==='subject'){
   const v=normSubject(t);

   return (
     v &&
     v.length<=120
   )
     ? v
     : '';
 }

 if(field==='grade'){
   const v=normGrade(t);

   return /^Grade\s+(?:[1-9]|1[0-2])$/i.test(v)
     ? v
     : '';
 }

 if(field==='preferred_language'){
   const v=normLang(t);

   return [
     'English',
     'Arabic',
     'French',
     'en',
     'ar',
     'fr'
   ].includes(v)
     ? v
     : '';
 }

 return '';
}

